const pptxgen = require('pptxgenjs');
let pres = new pptxgen();

// Apply Midnight Executive theme and layout
pres.layout = 'LAYOUT_WIDE'; // 13.3" x 7.5"
const primaryColor = '1E2761';
const secondaryColor = 'CADCFC';
const accentColor = 'FFFFFF';
const bodyFont = 'Calibri';
const headerFont = 'Cambria';

// --- Slide 1: Title Slide ---
pres.addSlide().addText(
    'INDIA: A Tapestry of Culture, History, and Innovation',
    { x: 1.0, y: 1.5, fontSize: 44, bold: true, color: accentColor, align: 'center', margin: 0, w: '80%', fontFace: headerFont }
);
pres.getSlide(1).addText(
    'A Detailed Presentation for Achal Nawal',
    { x: 1.0, y: 3.5, fontSize: 20, color: secondaryColor, align: 'center', w: '80%', fontFace: bodyFont }
);
pres.getSlide(1).back = primaryColor;


// --- Slide 2: Overview ---
let slide2 = pres.addSlide();
slide2.back = accentColor;
slide2.addText('Overview of India', { x: 0.5, y: 0.5, fontSize: 36, bold: true, color: primaryColor, fontFace: headerFont });

const overviewText = [
    { text: 'Diverse Culture: A mosaic of traditions, languages, and festivals.', options: { bullet: true, fontSize: 16, color: '36454F', fontFace: bodyFont, breakLine: true } },
    { text: 'Rich History: Ancient civilizations, empires, and struggle for independence.', options: { bullet: true, fontSize: 16, color: '36454F', fontFace: bodyFont, breakLine: true } },
    { text: 'Economic Hub: Rapidly growing economy and global innovation leader.', options: { bullet: true, fontSize: 16, color: '36454F', fontFace: bodyFont } },
];
slide2.addText(overviewText, { x: 0.8, y: 1.8, w: '50%', margin: 0 });

// Placeholder for visual element (Image or Icon grid)
slide2.addShape(pres.ShapeType.RECTANGLE, { x: 7.0, y: 1.5, w: 5.5, h: 5.5, fill: { color: secondaryColor }, transparency: 30 });
slide2.addText('Visual Element Placeholder (Culture Map / Icons)', { x: 7.0, y: 4.0, w: 5.5, h: 1.0, align: 'center', fontSize: 14, color: primaryColor });


// --- Slide 3: History & Heritage ---
let slide3 = pres.addSlide();
slide3.back = 'F2F2F2'; // Off-white for contrast
slide3.addText('History & Heritage', { x: 0.5, y: 0.3, fontSize: 36, bold: true, color: primaryColor, fontFace: headerFont });

const history = [
    { text: 'Ancient Civilizations: Indus Valley, Vedic Era.', options: { fontSize: 16, bold: true, color: primaryColor, fontFace: bodyFont } },
    { text: 'Empires: Mauryan, Gupta, Mughal Golden Ages.', options: { fontSize: 16, bold: true, color: primaryColor, fontFace: bodyFont } },
    { text: 'Struggle for Independence: A defining movement.', options: { fontSize: 16, bold: true, color: primaryColor, fontFace: bodyFont } },
];

slide3.addText(history, { x: 0.8, y: 1.2, w: '90%', margin: 0, breakLine: true });

// Placeholder for a timeline visualization (interactive element concept)
slide3.addShape(pres.ShapeType.LINE, { x: 0.8, y: 3.5, w: 12.0, h: 0, line: { color: primaryColor, width: 2 } });
slide3.addText('Interactive Timeline Visualization Placeholder', { x: 0.8, y: 3.8, w: 12.0, align: 'center', fontSize: 14, color: '36454F' });


// --- Slide 4: Innovation & Economy (Aligning with Achal's Internship Focus) ---
let slide4 = pres.addSlide();
slide4.back = accentColor;
slide4.addText('Innovation & Economy', { x: 0.5, y: 0.5, fontSize: 36, bold: true, color: primaryColor, fontFace: headerFont });

const innovation = [
    { text: 'Global AI Leader: Focus on AI and Generative AI.', options: { bullet: true, fontSize: 18, color: '36454F', fontFace: bodyFont, breakLine: true } },
    { text: 'Startup Ecosystem: World’s third-largest.', options: { bullet: true, fontSize: 18, color: '36454F', fontFace: bodyFont, breakLine: true } },
    { text: 'Digital Transformation: Rapid adoption and growth.', options: { bullet: true, fontSize: 18, color: '36454F', fontFace: bodyFont } },
];
slide4.addText(innovation, { x: 0.8, y: 1.8, w: '50%', margin: 0 });

// Placeholder for chart (interactive element)
slide4.addShape(pres.ShapeType.CHART, {
    x: 6.5, y: 1.5, w: 6.0, h: 5.0,
    type: 'bar',
    data: [{
        name: 'Growth',
        labels: ['AI/GenAI', 'Startups', 'Digital'],
        values: [75, 60, 85]
    }],
    options: {
        title: 'Innovation & Growth Indicators',
        showTitle: true,
        chartColors: [primaryColor, '6D2E46', '00A896'],
        showValue: true,
        dataLabelPosition: 'ctr'
    }
});


// --- Slide 5: Conclusion ---
let slide5 = pres.addSlide();
slide5.back = primaryColor;
slide5.addText(
    'Conclusion: A Global Powerhouse',
    { x: 0.5, y: 2.5, fontSize: 36, bold: true, color: accentColor, align: 'center', w: '90%', fontFace: headerFont }
);
slide5.addText(
    'A blend of ancient legacy and future-focused innovation.',
    { x: 0.5, y: 4.0, fontSize: 20, color: secondaryColor, align: 'center', w: '90%', fontFace: bodyFont }
);


// Save the presentation
const outputPath = 'C:/Users/achal/Desktop/India_Presentation.pptx';
pres.writeFile(outputPath);
console.log(`Presentation saved to ${outputPath}`);

